namespace Softaxis.Restaurant.Domain.Entities;

/// <summary>
/// One action a till queued while it could not reach the server (take order, add items, send,
/// serve, take payment), recorded when the upload processes it. The OpId is generated by the till;
/// a re-upload of the same action finds its row here and is skipped, so nothing is applied twice.
/// </summary>
public sealed class OfflineOp
{
    public Guid Id { get; private set; } = Guid.NewGuid();
    public string OpId { get; private set; } = null!;
    public string Kind { get; private set; } = null!;
    public Guid? OrderId { get; private set; }
    /// <summary>applied | rejected</summary>
    public string Status { get; private set; } = "applied";
    public string? Error { get; private set; }
    public DateTime OccurredAt { get; private set; }
    public DateTime ProcessedAt { get; private set; } = DateTime.UtcNow;
    public Guid? ProcessedByUserId { get; private set; }

    private OfflineOp() { }

    public OfflineOp(string opId, string kind, DateTime occurredAt, Guid? processedBy)
    {
        OpId = opId; Kind = kind; OccurredAt = occurredAt; ProcessedByUserId = processedBy;
    }

    public void Applied(Guid? orderId) { Status = "applied"; OrderId = orderId; Error = null; }
    public void Rejected(Guid? orderId, string error) { Status = "rejected"; OrderId = orderId; Error = error; }
}
